insert into public.moves (name, type, power, accuracy_stat, accuracy_skill, damage_stat, effect, target, category)
select name, type::public.pokemon_type, power, accuracy_stat, accuracy_skill, damage_stat, effect, target, category
from incoming
on conflict (name) do update set
  type = excluded.type,
  power = excluded.power,
  accuracy_stat = excluded.accuracy_stat,
  accuracy_skill = excluded.accuracy_skill,
  damage_stat = excluded.damage_stat,
  effect = excluded.effect,
